quota_scripts.script:
function httpErr(e) {
  var m = e && e.message ? String(e.message) : String(e);
  if (m.indexOf("HTTP ") === 0) return m;
  if (m.indexOf("JSON parse: ") === 0) return "Parse: " + m.slice(12);
  return "Network: " + m;
}
function moneyNum(t) {
  var out = "";
  var dot = false;
  for (var i = 0; i < t.length; i++) {
    var ch = t.charAt(i);
    if (ch >= "0" && ch <= "9") { out += ch; }
    else if (ch === "." && !dot && out !== "") { out += ch; dot = true; }
  }
  if (out === "" || out === ".") return null;
  var n = Number(out);
  return isNaN(n) ? null : n;
}
function tierName(wn) {
  var s = String(wn).toLowerCase().split(" ").join("");
  if (s.indexOf("week") !== -1 || s.indexOf("7d") !== -1 || s.indexOf("seven") !== -1) return "weekly_limit";
  if (s.indexOf("5h") !== -1 || s.indexOf("five") !== -1) return "five_hour";
  if (s.indexOf("month") !== -1 || s.indexOf("30d") !== -1) return "monthly";
  return null;
}
var base = String(ctx.baseUrl || "");
while (base.length > 0 && base.charAt(base.length - 1) === "/") base = base.slice(0, -1);
if (base.length > 3 && base.slice(-3) === "/v1") base = base.slice(0, -3);
if (base === "") return { success: false, error: "Missing ctx.baseUrl" };
var body;
try {
  body = http.get(base + "/v1/magpie/quotas?kept=1", {});
} catch (e) {
  return { success: false, error: httpErr(e) };
}
if (body == null || typeof body !== "object" || Array.isArray(body) || !Array.isArray(body.data)) {
  return { success: false, error: "HTTP 200 but no data array" };
}
var items = body.data;
var plan = null;
var dropped = [];
var notes = [];
var balNumSum = 0.0;
var balNumUnit = null;
var balNumCount = 0;
var balText = null;
var entryErr = null;
for (var i = 0; i < items.length; i++) {
  var q = items[i];
  if (q == null || typeof q !== "object" || Array.isArray(q)) continue;
  var kind = typeof q.kind === "string" ? q.kind : "";
  if (kind === "subscription") continue;
  var entryFailed = typeof q.error === "string" && q.error !== "";
  if (kind === "balance") {
    if (entryFailed) { entryErr = q.error; continue; }
    if (Array.isArray(q.windows)) {
      for (var w = 0; w < q.windows.length; w++) {
        var win = q.windows[w];
        if (win != null && typeof win.balance === "number") {
          balNumSum += win.balance;
          if (balNumUnit === null && typeof win.unit === "string" && win.unit !== "") balNumUnit = win.unit;
          balNumCount++;
        }
      }
    }
    if (balText === null && typeof q.balance === "string" && q.balance.trim() !== "") balText = q.balance;
  } else if (kind === "plan" && plan === null) {
    var lvl = typeof q.plan === "string" && q.plan !== "" ? q.plan : null;
    var tiers = [];
    if (Array.isArray(q.windows)) {
      for (var j = 0; j < q.windows.length; j++) {
        var win = q.windows[j];
        if (win == null || typeof win !== "object" || Array.isArray(win)) continue;
        if (win.text === true || win.unlimited === true) { dropped.push(String(win.name)); continue; }
        var used = typeof win.used === "number" ? win.used
          : (typeof win.remaining === "number" ? 100 - win.remaining : null);
        if (used === null) { dropped.push(String(win.name)); continue; }
        var tn = tierName(win.name);
        if (tn === null) { dropped.push(String(win.name)); continue; }
        tiers.push({
          name: tn,
          utilization: used,
          resets_at: typeof win.resetsAt === "string" && win.resetsAt !== "" ? win.resetsAt : null,
          unit: "prompt_count"
        });
      }
    }
    if (tiers.length > 0) plan = { level: lvl, tiers: tiers };
  }
}
if (plan !== null && dropped.length > 0) notes.push("dropped windows: " + dropped.join(", "));
if (entryErr !== null) notes.push("balance entry error: " + entryErr);
var balance = null;
if (balNumCount > 0) {
  balance = { remaining: balNumSum, total: null, used: null, currency: balNumUnit, is_valid: true };
  if (balText !== null) notes.push("text balance ignored; using numeric windows sum");
} else if (balText !== null) {
  var mv = moneyNum(balText);
  if (mv !== null) {
    balance = {
      remaining: mv,
      total: null,
      used: null,
      currency: balText.indexOf("$") !== -1 ? "USD" : (balText.indexOf("¥") !== -1 ? "CNY" : null),
      is_valid: true
    };
  } else {
    notes.push("balance text not parseable: " + balText);
  }
}
return {
  success: true,
  error: notes.length > 0 ? notes.join("; ") : null,
  balance: balance,
  coding_plan: plan
};
